abstract class Discount {
    protected String discountCode;
    protected Discount(String code) { this.discountCode = code; }
    public abstract double calculateDiscount(double price);
    public void applyDiscount(double price) {
        double disc  = calculateDiscount(price);
        double final_ = price - disc;
        System.out.println("Code: " + discountCode + " | Original: ₹" + price
                          + " | Discount: ₹" + disc + " | Final: ₹" + final_);
    }
}
class FlatDiscount extends Discount {
    private double flatAmount;
    public FlatDiscount(String code, double amount) {
        super(code); this.flatAmount = amount;
    }
    @Override
    public double calculateDiscount(double price) {
        return Math.min(flatAmount, price);
    }
}
class PercentageDiscount extends Discount {
    private double percentage;
    public PercentageDiscount(String code, double pct) {
        super(code); this.percentage = pct;
    }
    @Override
    public double calculateDiscount(double price) {
        return price * percentage / 100;
    }
}
// Usage:
new FlatDiscount("FLAT100", 100).applyDiscount(599);
new PercentageDiscount("SAVE20", 20).applyDiscount(1500);

