abstract class DatabaseMigration {
    protected String dbName;
    public DatabaseMigration(String dbName) { this.dbName = dbName; }

    // Template method
    public final void migrate() {
        takeBackup();
        runMigrationScripts();
        if (!validateResult()) {
            System.out.println("Validation failed — initiating rollback");
            rollback();
            return;
        }
        sendReport(true);
    }

    // Abstract — each migration type handles differently
    protected abstract void runMigrationScripts();
    protected abstract boolean validateResult();

    // Concrete shared behavior
    private void takeBackup() {
        System.out.println("Taking backup of " + dbName + "...");
    }
    private void sendReport(boolean success) {
        System.out.println("Migration " + (success ? "SUCCEEDED" : "FAILED") + " for " + dbName);
    }
    // Hook — optional rollback
    protected void rollback() {
        System.out.println("Rolling back " + dbName + " to backup");
    }
}
class MySQLMigration extends DatabaseMigration {
    public MySQLMigration(String db) { super(db); }
    @Override protected void runMigrationScripts() {
        System.out.println("Running MySQL V2.1 → V2.2 scripts");
    }
    @Override protected boolean validateResult() {
        System.out.println("Validating MySQL schema...");
        return true;
    }
}

